{
  "name": "MYTHEN一维微条带X射线探测器",
  "name_en": "MYTHEN 1D Microstrip X-ray Detector",
  "manufacturer": "DECTRIS",
  "description": "MYTHEN是一种一维位置敏感微条带X射线探测器，可快速记录衍射强度随角度或通道的分布，常用于粉末X射线衍射、同步辐射束线实验和其他需要高速读出的X射线探测测量。",
  "description_en": "MYTHEN is a one-dimensional position-sensitive microstrip X-ray detector that rapidly records diffraction intensity versus angle or channel. It is commonly used for powder X-ray diffraction, synchrotron beamline experiments, and other X-ray measurements requiring fast readout.",
  "tag_hints": [
    "X-ray detector",
    "microstrip detector",
    "1D position-sensitive detection",
    "powder diffraction",
    "synchrotron beamline",
    "fast readout",
    "flat-field correction"
  ],
  "actions": [
    {
      "action_name": "auto-acquire",
      "description": "开始一次探测采集。",
      "description_en": "Start a detector acquisition."
    },
    {
      "action_name": "auto-canMonitor",
      "description": "获取设备是否可作为监视通道使用。",
      "description_en": "Get whether the device can be used as a monitor channel."
    },
    {
      "action_name": "auto-canStopCount",
      "description": "获取设备是否支持停止计数并返回结果。",
      "description_en": "Get whether the device can stop counting and return results."
    },
    {
      "action_name": "auto-changeTime",
      "description": "修改采集时间。",
      "description_en": "Change the acquisition time."
    },
    {
      "action_name": "auto-finish",
      "description": "结束当前采集或计数过程。",
      "description_en": "Finish the current acquisition or counting process."
    },
    {
      "action_name": "auto-getValue",
      "description": "获取当前测量值。",
      "description_en": "Get the current measured value."
    },
    {
      "action_name": "auto-isCounting",
      "description": "获取设备是否正在计数。",
      "description_en": "Get whether the device is currently counting."
    },
    {
      "action_name": "auto-readFlatfield",
      "description": "获取平场校正状态。",
      "description_en": "Get the flat-field correction state."
    },
    {
      "action_name": "auto-readFlip",
      "description": "获取数据翻转状态。",
      "description_en": "Get the data flip state."
    },
    {
      "action_name": "auto-readout",
      "description": "读出当前采集数据。",
      "description_en": "Read out the current acquisition data."
    },
    {
      "action_name": "auto-setCountTime",
      "description": "设置计数时间。",
      "description_en": "Set the count time."
    },
    {
      "action_name": "auto-setFlatfield",
      "description": "设置平场校正状态。",
      "description_en": "Set the flat-field correction state."
    },
    {
      "action_name": "auto-setFlip",
      "description": "设置数据翻转状态。",
      "description_en": "Set the data flip state."
    },
    {
      "action_name": "auto-setPresetValue",
      "description": "设置指定通道的预置计数值。",
      "description_en": "Set the preset count value for a specified channel."
    },
    {
      "action_name": "auto-settings",
      "description": "配置探测器测量参数。",
      "description_en": "Configure detector measurement settings."
    },
    {
      "action_name": "auto-startCount",
      "description": "开始计数。",
      "description_en": "Start counting."
    },
    {
      "action_name": "auto-stopCount",
      "description": "停止计数。",
      "description_en": "Stop counting."
    },
    {
      "action_name": "auto-wait",
      "description": "等待当前计数完成。",
      "description_en": "Wait for the current counting operation to finish."
    },
    {
      "action_name": "auto-waitFinish",
      "description": "等待采集结束。",
      "description_en": "Wait for the acquisition to finish."
    }
  ]
}

